"""Bounded beam search for character-prefix-aware DataFrame column ordering."""

import heapq
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Optimize serialized Trie reuse with a bounded beam over merge blocks."""

    def __init__(self, df: pd.DataFrame = None):
        """Retain the optional frame and expose the latest row-specific orders."""
        self.df = df
        self._last_orders = None

    @staticmethod
    def _cell_string(value) -> str:
        """Serialize one value, replacing scalar missing values with an empty string."""
        missing = pd.isna(value)
        if isinstance(missing, (bool, np.bool_)) and bool(missing):
            return ""
        return str(value)

    @staticmethod
    def _lcp(a: str, b: str) -> int:
        """Return exact common-prefix length using binary-searched C-level slices."""
        if a == b:
            return len(a)
        lo, hi = 0, min(len(a), len(b))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if a[:mid] == b[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Score a collection by LCP lengths of lexicographically adjacent rows."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        return sum(
            len(b) if a == b else cls._lcp(a, b)
            for a, b in zip(ordered, ordered[1:])
        )

    @staticmethod
    def _positions(columns):
        """Map stringified labels to source positions, retaining duplicate ambiguity."""
        out = {}
        for i, col in enumerate(columns):
            out.setdefault(str(col), []).append(i)
        return out

    @classmethod
    def _edges(cls, columns, dependencies, blocks):
        """Translate dependencies and merge adjacency into directed source-index edges."""
        pos = cls._positions(columns)
        edges, seen = [], set()

        def add(a, b):
            if a != b and (a, b) not in seen:
                seen.add((a, b))
                edges.append((a, b))

        for pair in dependencies or []:
            if len(pair) == 2:
                aa, bb = pos.get(str(pair[0]), []), pos.get(str(pair[1]), [])
                if len(aa) == len(bb) == 1:
                    add(aa[0], bb[0])

        for block in blocks:
            for a, b in zip(block, block[1:]):
                add(a, b)
        return edges

    @classmethod
    def _constrained_order(cls, m, preference, columns, dependencies, blocks):
        """Topologically repair a preference while preserving all valid constraints."""
        outgoing = [[] for _ in range(m)]
        indegree = [0] * m
        for a, b in cls._edges(columns, dependencies, blocks):
            outgoing[a].append(b)
            indegree[b] += 1

        rank = {x: i for i, x in enumerate(preference)}
        heap = [(rank.get(i, m + i), i) for i in range(m) if indegree[i] == 0]
        heapq.heapify(heap)
        result = []

        while heap:
            _, node = heapq.heappop(heap)
            result.append(node)
            for nxt in outgoing[node]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    heapq.heappush(heap, (rank.get(nxt, m + nxt), nxt))

        return result if len(result) == m else list(preference)

    @staticmethod
    def _stats(text):
        """Compute length-weighted repetition statistics independently per column."""
        n, m = text.shape
        result = []
        for j in range(m):
            counts = {}
            for value in text[:, j]:
                counts[value] = counts.get(value, 0) + 1
            pairs = sum(len(v) * c * (c - 1) for v, c in counts.items())
            repeat = sum(len(v) * max(0, c - 1) for v, c in counts.items())
            total = sum(len(v) * c for v, c in counts.items())
            result.append((pairs, repeat, total))
        return result

    @staticmethod
    def _merge_blocks(m, columns, requested):
        """Build deterministic atomic blocks from valid requested merge pairs."""
        parent = list(range(m))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        pos = {}
        for i, col in enumerate(columns):
            pos.setdefault(str(col), []).append(i)

        for pair in requested or []:
            if len(pair) != 2:
                continue
            aa, bb = pos.get(str(pair[0]), []), pos.get(str(pair[1]), [])
            if len(aa) == len(bb) == 1:
                ra, rb = find(aa[0]), find(bb[0])
                if ra != rb:
                    parent[rb] = ra

        groups = {}
        for i in range(m):
            groups.setdefault(find(i), []).append(i)
        return sorted((sorted(v) for v in groups.values()), key=lambda x: x[0])

    @classmethod
    def _affinity(cls, text, left, right):
        """Measure length-weighted repeated right values inside equal-left groups."""
        groups = {}
        for row, value in enumerate(text[:, left]):
            groups.setdefault(value, []).append(row)

        score = 0
        for rows in groups.values():
            if len(rows) < 2:
                continue
            counts = {}
            for row in rows:
                value = text[row, right]
                counts[value] = counts.get(value, 0) + 1
            score += sum(len(v) * c * (c - 1) for v, c in counts.items())
        return score

    @classmethod
    def _block_candidates(cls, text, stats, blocks):
        """Construct two bounded lookahead beam paths over high-value merge blocks."""
        if len(blocks) <= 1:
            return [[x for block in blocks for x in block]]

        mass = [sum(stats[j][0] for j in block) for block in blocks]
        active = sorted(
            range(len(blocks)),
            key=lambda k: (-mass[k], blocks[k][0]),
        )[:32]

        reps = [blocks[k][:2] for k in active]
        affinity = {}
        for ia, a in enumerate(active):
            for ib, b in enumerate(active):
                if ia != ib:
                    affinity[ia, ib] = sum(
                        cls._affinity(text, x, y)
                        for x in reps[ia] for y in reps[ib]
                    )

        # A state is (path, remaining, score).  The beam retains distinct
        # topologies instead of committing to one greedy successor.
        beam = [((), frozenset(range(len(active))), 0)]
        width = 4
        for _ in range(len(active)):
            expanded = []
            for path, remaining, value in beam:
                if not remaining:
                    expanded.append((path, remaining, value))
                    continue
                previous = path[-1] if path else None
                for nxt in remaining:
                    gain = mass[active[nxt]]
                    if previous is not None:
                        gain += affinity.get((previous, nxt), 0)
                    newpath = path + (nxt,)
                    left = remaining - {nxt}
                    # Remaining mass provides a deterministic lookahead bound.
                    bound = value + gain + sum(
                        mass[active[x]] for x in left
                    )
                    expanded.append((newpath, left, value + gain + bound // 1000000))
            expanded.sort(
                key=lambda s: (-s[2], tuple(active[x] for x in s[0]))
            )
            beam = expanded[:width]

        candidates = []
        active_set = set(active)
        for path, _, _ in beam[:2]:
            used = {active[x] for x in path}
            tail = sorted(
                (k for k in range(len(blocks)) if k not in used),
                key=lambda k: (-mass[k], blocks[k][0]),
            )
            candidates.append(
                [col for k in [active[x] for x in path] + tail for col in blocks[k]]
            )
        return candidates

    @staticmethod
    def _serialize(text, orders):
        """Serialize each source row using its row-specific column permutation."""
        return [
            "".join(text[row, col] for col in orders[row])
            for row in range(text.shape[0])
        ]

    @staticmethod
    def _materialize(df, source, orders, serialized):
        """Sort by serialized keys and copy original cells under each chosen order."""
        row_order = sorted(range(len(orders)), key=lambda r: (serialized[r], r))
        values = np.empty(source.shape, dtype=object)
        public = []

        for out, row in enumerate(row_order):
            order = orders[row]
            values[out, :] = [source[row, col] for col in order]
            public.append([df.columns[col] for col in order])

        result = pd.DataFrame(
            values,
            index=df.index.take(row_order),
            columns=list(df.columns),
        )
        return result, public

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List]]:
        """Evaluate a frequency baseline and bounded beam-generated block paths."""
        if not isinstance(df, pd.DataFrame):
            raise TypeError("df must be a pandas DataFrame")

        n, m = df.shape
        if n == 0 or m == 0:
            result = df.copy()
            orders = [[] for _ in range(n)]
            self._last_orders = orders
            return result, orders

        source = df.to_numpy(dtype=object, copy=True)
        text = np.empty((n, m), dtype=object)
        for j in range(m):
            text[:, j] = [self._cell_string(v) for v in source[:, j]]

        stats = self._stats(text)
        columns = list(df.columns)
        blocks = self._merge_blocks(m, columns, col_merge)

        baseline = [
            j for j, stat in sorted(
                enumerate(stats),
                key=lambda x: (-x[1][0], -x[1][1], -x[1][2], x[0]),
            )
        ]
        preferences = [baseline]
        preferences.extend(self._block_candidates(text, stats, blocks))

        best_score = -1
        best_orders = None
        best_serialized = None

        for preference in preferences[:3]:
            order = self._constrained_order(
                m, preference, columns, one_way_dep, blocks
            )
            orders = [order[:] for _ in range(n)]
            serialized = self._serialize(text, orders)
            score = self._trie_score(serialized)
            if score > best_score:
                best_score = score
                best_orders = orders
                best_serialized = serialized

        result, public_orders = self._materialize(
            df, source, best_orders, best_serialized
        )
        if result.shape != df.shape:
            raise RuntimeError("Reordering changed DataFrame shape")

        self._last_orders = public_orders
        return result, public_orders

